// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Edebî terimler, anlatıcı, bakış açısı ve metin çözümleme (kolay).
const ozLiterature14Kolay = <(String, String, List<String>, String)>[
  ('Bütün köy, düğün için meydanda toplandı. Cümledeki \'köy\' sözüyle köyde yaşayan insanlar kastedildiğine göre burada hangi söz sanatı vardır?', 'Mecaz-ı mürsel', ['Açık istiare', 'Kapalı istiare', 'Hüsnütalil'], 'Köy sözcüğü benzetme olmadan, yer–yerleşen ilişkisiyle halkı anlatmıştır; bu ad aktarmasıdır.'),
  ('\'Yaşar Kemal\'i üçüncü kez okuyorum.\' cümlesindeki ad aktarmasının dayandığı ilgi hangisidir?', 'Sanatçı ile eseri', ['Parçayı söyleyip bütünü kastetme', 'Yer ile yerleşeni', 'Araç ile işi'], 'Yaşar Kemal denince yazarın kitapları kastedilmiştir; ilgi sanatçı–eser ilişkisidir.'),
  ('\'Susadığım için üç bardak içtim.\' cümlesindeki \'bardak\' sözü hangi ilgiyle kullanılmıştır?', 'Kap ile içindekini anlatma', ['Parçayı söyleyip bütünü anlatma ilgisi', 'Sanatçı ile eseri anlatma', 'Neden söylenip sonucun kastedildiği ilgi'], 'İçilen şey su ya da çaydır; bardak, içindekini anlatan bir ad aktarmasıdır.'),
  ('\'Ocak\' sözcüğü aşağıdaki cümlelerin hangisinde mecaz-ı mürsel olarak kullanılmıştır?', 'Bu ocağın tüten bacası hiç sönmesin, çocukları çoğalsın.', ['Ocakta çorba kaynıyordu, evi güzel bir koku sarmıştı.', 'Ocak ayında Erzurum\'da sıcaklık eksi yirmi dereceye düştü.', 'Mutfaktaki ocağı kapatmayı unutmuşum.'], 'İlk cümlede ocak, aileyi anlatır; diğerlerinde sözcük gerçek anlamlıdır.'),
  ('Mecaz anlamın anlaşılmasını sağlayan, gerçek anlamı ise engelleyen ipucuna ne ad verilir?', 'Karine', ['Mübalağa', 'Kafiye', 'Tenasüp'], 'Söz sanatlarında gerçek anlamı engelleyen ve mecaza götüren ipucuna karine denir.'),
  ('\'Yetmiş baş koyun sürüye katıldı.\' cümlesinde \'baş\' sözcüğü ile aşağıdakilerden hangisi gerçekleşmiştir?', 'Hayvanın bir parçasıyla hayvanın kendisinin anlatılması', ['Koyunun bir insana benzetilip insan gibi konuşturulması', 'Koyunun başının özellikle övülmesi', 'Koyun sürüsünün abartılarak olduğundan büyük gösterilmesi'], 'Baş, bir parça olarak bütün hayvanı anlatır; bu bir ad aktarmasıdır.'),
  ('\'Salon ayağa kalkıp uzun süre alkışladı.\' cümlesinde hangi söz sanatı bulunur?', 'Mecaz-ı mürsel', ['Tezat, karşıt kavramların yan yana getirilmesi', 'Cinas, sesteş sözcüklerle yapılan söz oyunu', 'Tevriye, iki anlamlı sözcüğün kullanımı'], 'Salon, içindeki izleyicileri anlatan bir ad aktarmasıdır (yer–yerleşen).'),
  ('\'Bu mahalleden bir ses yükseldi: Su yok!\' cümlesinde mahalle ile kastedilen nedir?', 'Mahallede oturanlar', ['Mahallenin sokakları', 'Mahallenin camisi', 'Mahallenin tarihi'], 'Yer adı söylenip orada yaşayanlar anlatılmıştır; mecaz-ı mürsel örneğidir.'),
  ('\'Ne kadar çok okursam, o kadar az bildiğimi anlıyorum.\' cümlesi hangi anlatım özelliğine örnektir?', 'Paradoks', ['Hüsnütalil', 'Mecaz-ı mürsel', 'Kişileştirme'], 'Görünüşte çelişkili olan ama derin bir doğruyu anlatan söz paradokstur.'),
  ('Aşağıdaki cümlelerin hangisi paradoks özelliği taşımaz?', 'Bu yıl kış erken geldi, bahçedeki ağaçlar yapraklarını erkenden döktü.', ['Özgürlüğüm, kendi koyduğum sınırlarda başlıyor.', 'En büyük güç, güçsüzlüğünü bilmektir.', 'Beni en çok anlayan, hiç konuşmayan dostum oldu.'], 'Seçeneklerden yalnız biri çelişki taşımayan, düz bir gözlem cümlesidir.'),
  ('\'Acı bir tatlılıkla gülümsedi.\' cümlesindeki \'acı tatlılık\' ifadesi hangi sanatla kurulmuştur?', 'Oksimoron', ['Tenasüp', 'Aliterasyon', 'Tevriye'], 'Birbirine zıt iki nitelik tek ifade içinde birleştirilmiştir.'),
  ('\'Gece gündüz çalıştı, hiç dinlenmedi.\' cümlesinde hangi söz sanatı bulunmaktadır?', 'Tezat', ['Tenasüp', 'Kinaye', 'Teşhis'], 'Gece ile gündüz karşıt sözcüklerdir; birlikte kullanımları tezat oluşturur.'),
  ('\'Düşmanın dostluğu, dostun düşmanlığından iyidir.\' cümlesinde hangi sanat belirgindir?', 'Antitez', ['Cinas', 'Mecaz-ı mürsel', 'Teşhis'], 'Karşıt iki yargının yan yana getirilmesiyle düşünce vurgulanmıştır.'),
  ('Bir öyküde yazar, kahramanın cebindeki durmuş saati sık sık gösteriyor ve bu saat kahramanın yaşamında zamanın donmuş olduğunu düşündürüyor. Bu saat metinde hangi işlevi görmektedir?', 'Sembol', ['Betimleme', 'Anlatıcı müdahalesi', 'Diyalog'], 'Somut bir nesne, soyut bir anlamı temsil ettiği için sembol olarak kullanılmıştır.'),
  ('Aşağıdakilerden hangisi evrensel anlamı olan bir semboldür?', 'Terazinin adaleti simgelemesi', ['Bir şairin çocukluğundaki sokak lambası', 'Yazarın kedisinin adı', 'Romancının kullandığı mavi mürekkep'], 'Terazi pek çok kültürde adalet kavramıyla bağdaştırılır; diğerleri kişisel ayrıntıdır.'),
  ('Kültürler arasında benzer biçimde yinelenen \'bilge yaşlı\', \'gölge\', \'kahraman\' gibi köken kalıplarına hangi kavram adı verilir?', 'Arketip', ['Leitmotiv', 'Karine', 'Hüsnütalil'], 'Jung\'un kolektif bilinçdışı düşüncesine dayanan bu ortak kalıplara arketip denir.'),
  ('Bir köyde herkesin gözleri kapalı yaşadığı, gözlerini açan bir kişinin dışlandığı öykü bütünüyle toplumun gerçeği görmek istemeyişini anlatıyorsa bu öykü için hangi nitelik uygundur?', 'Alegorik anlatı', ['Gözlemci bakış açılı anlatı', 'Bilimsel açıklama', 'Öğretici gezi yazısı'], 'Olayların bütününün ikinci bir anlamı dile getirmesi alegorinin tanımıdır.'),
  ('\'Ben bu yolda bir başıma yürüdüm, ömrümün sonuna dek.\' dizesinde \'yol\' sözcüğü nasıl kullanılmıştır?', 'Hayatı simgeleyen bir sembol olarak', ['Gerçek bir caddeyi anlatan yan anlamıyla', 'Bir mekânın ayrıntılı betimlemesi olarak', 'Terim anlamlı bir sözcük olarak'], 'Ömrün sonuna dek yürümek ifadesi yolu hayat yolculuğunun simgesi yapar.'),
  ('Aşağıdaki dizelerin hangisinde koku imgesi baskındır?', 'Yeni biçilmiş çimen kokusu doldurdu sokağı', ['Kızıl güneş battı dağların ardında, ufuk kızardı', 'Uzaktan bir ney sesi geliyordu', 'Karanlık odada tek mum titriyordu'], 'Koku duyusuna seslenen ifade yalnız birincisindedir; diğerleri görme, işitme ve dokunma duyularına seslenir.'),
  ('Aşağıdaki dizelerin hangisinde işitsel imge öne çıkar?', 'Gecenin sessizliğini bozdu bir kapı gıcırtısı', ['Gül kırmızısı bir akşam çöktü şehre', 'Bal tadında bir yaz kalmıştı dilimde', 'Yünlü bir battaniye gibi sıcaktı odanın havası'], 'İşitsel imge ses duyusuna seslenir; kapı gıcırtısı bir sestir.'),
  ('Masallarda \'kırk gün kırk gece\' ya da \'üç kardeş\' gibi öğelerin sürekli yinelenmesi aşağıdakilerden hangisi ile açıklanır?', 'Motif', ['Hüsnütalil', 'İstifham', 'Bilinç akışı'], 'Birçok anlatıda yinelenen küçük anlam birimine motif denir.'),
  ('\'Kök\' sözcüğü aşağıdaki cümlelerin hangisinde terim anlamıyla kullanılmıştır?', 'Bu fiilin kökü gel- biçimindedir.', ['Ağacın kökleri taşları yarmış.', 'Sorunun kökü çok eskiye dayanıyor.', 'Kökboyası giysiye iyi tutmuş.'], 'Dil bilgisinde bir sözcüğün ek almamış biçimini adlandıran söz terim anlamlıdır.'),
  ('\'Yaşlı komşumuz dün gece hakkın rahmetine kavuştu.\' cümlesinde \'öldü\' sözü yerine kullanılan ifade hangi kavramla adlandırılır?', 'Örtmece', ['Mübalağa', 'Tevriye', 'Paradoks'], 'Hoş görülmeyen ya da acı sözcüğün yerine yumuşak bir ifade kullanmaya örtmece (eufemizm) denir.'),
  ('Bir öyküde yaşlı bir terzinin dükkânını yıllarca kapatmayıp müşterisi gelmese de her sabah tezgâhını hazırlaması anlatılıyor. Bu öykünün teması aşağıdakilerden hangisi olabilir?', 'Alışkanlıkların ve geçmişe bağlılığın insanı ayakta tutması', ['Büyük şehirlerde kira artışı', 'Moda sektörünün geleceği', 'Çocukların terzilik öğrenmesi'], 'Terzinin boşuna da olsa her sabah dükkânı açması, bağlılık ve alışkanlık temasına işaret eder.'),
  ('Bir romanda yoksul bir ailenin çocuklarını okutmak için verdiği mücadele ayrıntılı biçimde işleniyor. Bu romanın en uygun teması hangisidir?', 'Eğitim uğruna verilen fedakârlık', ['Doğa sevgisi ve doğayı koruma bilinci', 'Mekânın tarihî özellikleri ve mimarisi', 'Kahramanın çocukluk anıları ve oyunları'], 'Romanın bütününü kapsayan öğe, eğitim uğruna yapılan fedakârlıktır.'),
  ('Bir metnin \'savaşın insanı yalnızlaştırdığı\' görüşünü savunduğu biliniyor. Bu cümle metnin neyini ifade eder?', 'Ana düşüncesini', ['Anlatıcısını ve bakış açısını', 'Konusunu ve ana olay örgüsünü', 'Mekânını'], 'Metnin vermek istediği temel yargı ana düşüncedir.'),
  ('Aşağıdakilerden hangisi bir eserin teması olamaz?', 'Kahramanın adı Ahmet\'tir.', ['Aşk ve ayrılık', 'Vatan sevgisi', 'Adaletsizlik'], 'Tema, eserin kapsadığı genel kavram ya da konudur; bir kişinin adı tema olamaz.'),
  ('Yazarın anlatıcı aracılığıyla bir olayı \'ben\' dilinden anlatması ve bunu kendi gerçek yaşamından alması hangi türde sık görülür?', 'Otobiyografik anlatı', ['Fabl', 'Destan', 'Masal'], 'Yazarın kendi yaşamını birinci kişiyle anlattığı eserler otobiyografik anlatı örnekleridir.'),
  ('Bir romanın olayları baştan sona doğal sıra ile, yani olayların gerçekte olduğu sırayla aktarılıyorsa bu sıralama için ne denir?', 'Kronolojik sıralama', ['Geriye dönüşlerle kurulmuş çok katmanlı sıralama', 'Olayların yazarca karıştırıldığı bozuk sıralama', 'Zamanın hiç belirtilmediği zamansız anlatım'], 'Olayların gerçek zaman düzeniyle anlatılması kronolojik sıralamadır.'),
  ('Bir hikâyede \'O gece hiç uyumadı, sabaha kadar düşündü.\' cümlesi bir gecenin tamamını tek cümleyle aktarıyor. Bu işleme hangi ad verilir?', 'Özet', ['Duraklama', 'Sahne', 'Geriye dönüş'], 'Uzun bir zamanı kısa bir anlatımla aktarmaya özet denir.'),
  ('\'Yıllar önce babasının ona söylediği o söz, şimdi kulaklarında yeniden yankılandı.\' cümlesi anlatıda hangi zaman geçişini yapıyor?', 'Şimdiden geçmişe dönüş', ['Gelecekten bugüne gelme', 'Zamanı durdurma', 'Zamanı atlama'], 'Geçmişte söylenen sözün anımsanması, geriye dönüş işlevi görür.'),
  ('Kurmacada \'atmosfer\' (hava) terimi neyi karşılar?', 'Eserin okurda uyandırdığı genel duygu ve ortam izlenimini', ['Eserin yazıldığı yerin iklimini', 'Kahramanın doğduğu şehrin adını', 'Metnin sözcük sayısını'], 'Atmosfer, metnin yarattığı genel ruhsal havadır.'),
  ('Aşağıdakilerden hangisi açık mekâna örnektir?', 'Meydan', ['Hapishane hücresi', 'Kütüphane', 'Asansör'], 'Meydan çevresi kapalı olmayan açık bir alandır; diğerleri kapalı mekândır.'),
  ('Aşağıdakilerden hangisi bir kişinin yalnız dış görünüşünü anlatan betimleme örneğidir?', 'Boyu uzun, saçları kırlaşmış, gözleri çökük bir adamdı.', ['Cömert, hoşgörülü ve sakin bir insandı.', 'Her sabah erkenden kalkıp tarlaya çıkardı.', 'Kızdığı zaman kimseyle konuşmazdı.'], 'Yalnız fiziksel özellikler verilen cümle dış görünüş betimlemesidir.'),
  ('Kişinin belirgin özelliklerini abartarak alay amacıyla anlatan betimlemeye ne ad verilir?', 'Karikatürize betimleme', ['Bilimsel betimleme, nesnel ve ölçülebilir tasvir', 'Teknik betimleme', 'Sahne betimlemesi'], 'Abartarak alaya alan tasvir karikatürize edilmiş betimlemedir.'),
  ('Bir yazar, kuşun kanatlarının uzunluğunu, gagasının biçimini ve rengini tarafsız ve ölçülebilir ayrıntılarla anlatıyor. Bu betimleme türü hangisidir?', 'Bilimsel (açıklayıcı) betimleme', ['İzlenimsel betimleme, yazarın duygusunu katan tasvir', 'Karikatürize betimleme, abartarak alaya alan tasvir', 'Duygusal betimleme, öznel izlenim aktaran tasvir'], 'Nesnel ve ölçülebilir bilgilere dayanan betimleme bilimsel betimlemedir.'),
  ('Hikâye boyunca düşünce ve davranışlarında hiçbir değişiklik göstermeyen karaktere ne ad verilir?', 'Statik (durağan) karakter', ['Dinamik (gelişen) karakter', 'Protagonist', 'Antagonist'], 'Değişmeyen kişi statik karakterdir.'),
  ('Bir anlatıcının \'Ali, hırslı ve bencil bir adamdı.\' demesi karakterin hangi biçimde tanıtıldığını gösterir?', 'Doğrudan karakterizasyon', ['Dolaylı karakterizasyon, davranışla tanıtma', 'Bilinç akışı', 'Dramatik ironi'], 'Anlatıcı, kişinin özelliğini açıkça söylediği için doğrudan tanıtma yapmıştır.'),
  ('Kahramanın bazı özelliklerini daha belirgin göstermek için ona zıt özelliklerde yaratılmış yan kişiye ne ad verilir?', 'Karşıt (foil) karakter', ['Figüran', 'Anlatıcı', 'Tip karakter'], 'Karşıt karakter, kahramanın özelliklerini zıtlık yoluyla belirginleştirir.'),
  ('Yüzeysel çizilmiş, tek bir özelliğiyle bilinen, olay içinde yalnızca belli bir işlevi yerine getiren kişiye ne denir?', 'Düz karakter', ['Yuvarlak karakter', 'Antik kahraman', 'Çoğul anlatıcı'], 'Tek bir özellikle donatılmış kişi düz karakterdir.'),
  ('Karmaşık bir ruh yapısına sahip, çelişkili duyguları olan ve okuru şaşırtabilen kişiye hangi ad verilir?', 'Yuvarlak karakter', ['Düz karakter, tek bir özelliğiyle bilinen kişi', 'Figüran, kısa süreli görünen ikincil kişi', 'Antagonist'], 'Çok yönlü, çelişkili ve gelişen kişi yuvarlak karakterdir.'),
  ('Bir romanda kahramanın en yakın dostu, kahramanın eylemlerini sorgulayan ve ona rehberlik eden biridir. Bu kişi için kullanılan terim hangisidir?', 'Mentor', ['Antagonist', 'Figüran', 'Anlatılan'], 'Kahramana rehberlik eden bilge kişi mentor olarak adlandırılır.'),
  ('Bir kişinin içinde bulunduğu toplumun kurallarıyla çatışması hangi çatışma türüne girer?', 'Birey–toplum çatışması', ['Birey–birey çatışması, iki kişi arasındaki mücadele', 'Birey–doğa çatışması, doğa güçlerine karşı mücadele', 'İç çatışma, kişinin kendi duygularıyla savaşması'], 'Birey kendi toplumunun değerleriyle ters düşünce birey–toplum çatışması doğar.'),
  ('Bir denizcinin fırtınaya karşı hayatta kalma mücadelesi anlatılıyorsa hangi çatışma türü vardır?', 'Birey–doğa çatışması', ['Birey–toplum çatışması', 'İç çatışma', 'Birey–birey çatışması'], 'Doğa güçlerine karşı verilen mücadele birey–doğa çatışmasıdır.'),
  ('Bir romandaki ana olayın yanında kahramanın komşusunun başından geçen bir olay da anlatılıyor. Bu ikinci olay için hangi terim uygundur?', 'Yan olay', ['Ana olay', 'Geriye dönüş', 'Kapanış'], 'Ana olaya bağlı olarak gelişen küçük olay yan olaydır.'),
  ('Kahramanın bir sorunla karşılaşıp çözemediği, durumun düğümlenip daha da karmaşıklaştığı bölüm klasik olay örgüsünde hangisidir?', 'Düğüm', ['Serim', 'Çözüm', 'Epilog'], 'Sorunun ortaya çıkıp karmaşıklaştığı bölüm düğümdür.'),
  ('Bir kahraman günlüğüne yazdığı notlar aracılığıyla anlatılıyorsa bu anlatının bakış açısı için hangisi doğrudur?', 'Birinci kişi, kahraman bakış açısı', ['İlahi bakış açısı', 'Gözlemci bakış açısı', 'Çoğul bakış açısı'], 'Günlük yazan kişi kendi gözünden anlattığı için kahraman bakış açısı oluşur.'),
  ('\'Ayşe, bugün biraz geç kalacağını söyledi.\' cümlesi hangi aktarma türüne örnektir?', 'Dolaylı aktarma', ['Doğrudan aktarma', 'Bilinç akışı', 'İç monolog'], 'Söz, anlatıcının cümlesine katıldığı için dolaylı aktarmadır.'),
  ('\'Ayşe, "Bugün biraz geç kalacağım," dedi.\' cümlesi hangi aktarma türüne örnektir?', 'Doğrudan aktarma', ['Dolaylı aktarma', 'Serbest dolaylı anlatım', 'Bilinç akışı'], 'Söz tırnak içinde olduğu gibi aktarıldığı için doğrudan aktarmadır.'),
  ('Bir anlatıcı, bulduğu bir el yazmasını okuyup içeriğini aktarıyor; asıl olaylar bu el yazmasının içinde geçiyor. Bu yapıya ne ad verilir?', 'Çerçeve öykü', ['Doğrusal ve bölümlere ayrılmamış tek parça kurgu', 'Sözcüklerin sesine dayanan ahenk kurma düzeni', 'Yazarın kendi yaşamını anlattığı otobiyografik yapı'], 'Asıl anlatıyı kuşatan ve bir yerde bulunmuş belgeyle başlayan kurgu çerçeve öyküdür.'),
  ('Bir yazar, \'Türkiye\'de her yıl yüz binlerce kişi kütüphaneye üye oluyor\' gibi rakamlarla savını destekliyorsa hangi yol kullanılmıştır?', 'Sayısal verilerden yararlanma', ['Tanık gösterme', 'Benzetme', 'Örneklendirme'], 'Rakamlarla desteklenen anlatım sayısal verilerden yararlanmadır.'),
  ('Bir yazı, okuru bir görüşe ikna etmek amacıyla karşıt görüşü çürütmeye çalışıyorsa baskın anlatım biçimi hangisidir?', 'Tartışma', ['Betimleme', 'Öyküleme', 'Açıklama'], 'Savunma ve çürütme içeren yazı tartışma anlatımıdır.'),
  ('Bir paragrafın ilk cümlesi ana fikri verir, sonraki cümleler ise örneklerle destekler. Bu paragraf yapısı hangisidir?', 'Tümdengelimli', ['Tümevarımlı', 'Karışık yapılı, ana düşüncesi ortada verilen', 'Zıtlık üzerine kurulu, ters anlamlı sözcüklerle ilerleyen'], 'Genelden özele ilerleyen paragraf tümdengelimlidir.'),
  ('Bir paragrafta önce örnekler ve ayrıntılar verilip son cümlede genel yargıya varılıyorsa paragraf hangi yoldan kurulmuştur?', 'Tümevarım', ['Tümdengelim', 'Karşılaştırma', 'Tanımlama'], 'Özelden genele giden paragraf tümevarımla kuruludur.'),
  ('Bir paragraf \'Kitap okumak insanı geliştirir.\' cümlesiyle başlıyor ve izleyen cümlelerde buna örnekler veriyorsa \'kitap okumak insanı geliştirir\' cümlesi paragrafta hangi işlevdedir?', 'Ana düşünce cümlesi', ['Örnek cümlesi, genel yargıyı somutlayan cümle', 'Geçiş cümlesi, iki bölümü bağlayan cümle', 'Sonuç cümlesi, paragrafı toparlayan cümle'], 'Ana yargıyı bildiren cümle ana düşünce cümlesidir.'),
  ('\'Bu nedenle\', \'sonuç olarak\' gibi ifadelerle başlayan cümlelerin paragrafta yeri en çok neresidir?', 'Sonuç bölümü', ['Giriş bölümü', 'Betimleme bölümü', 'Diyalog bölümü'], 'Bu ifadeler çoğunlukla sonuç cümlesinin başında bulunur.'),
  ('\'Bu şiir, bugüne kadar okuduğum en güzel şiirdi.\' cümlesinde hangi anlatım vardır?', 'Öznel', ['Nesnel', 'Bilimsel', 'Teknik'], 'Kişisel beğeni ve yargı içerdiğinden öznel anlatımdır.'),
  ('Aşağıdaki cümlelerin hangisi öznel bir yargı taşır?', 'Bu öykünün sonu çok başarısızdı.', ['Öykü iki bölümden oluşuyor.', 'Öykü 1950 yılında yayımlandı.', 'Öykünün baş kişisi bir öğretmendir.'], 'Beğeni içeren yargı öznel olduğu için seçenekler arasında yalnız ilki öznel yargıdır.'),
  ('Aşağıdakilerden hangisi nesnel bir ifadedir?', 'Roman, yazarın 1946\'da çıkardığı ilk eserdir.', ['Bu roman çok sıkıcıydı.', 'Roman ne yazık ki unutuldu.', 'Kahramanın kararları çok yanlıştı.'], 'Yayın tarihi doğrulanabilir bir bilgi olduğundan nesneldir.'),
  ('Edebî metinler konularına ve yazılış amaçlarına göre dört ana grupta incelenir. Aşağıdakilerden hangisi bu gruplardan biri değildir?', 'Bilimsel makale metinleri', ['Anlatmaya bağlı edebî metinler', 'Sahnelenmeye bağlı edebî metinler', 'Öğretmeye bağlı edebî metinler'], 'Edebî türler anlatmaya bağlı, sahnelenmeye bağlı, öğretmeye bağlı ve coşku-heyecan metinleri olarak dört gruba ayrılır; \'bilimsel makale metinleri\' bir grup adı değildir.'),
  ('Aşağıdakilerden hangisi anlatmaya bağlı edebî türlere örnektir?', 'Roman', ['Gazel, lirik bir nazım biçimi', 'Trajedi, sahnede oynanmak üzere yazılan oyun', 'Deneme, yazarın kişisel düşüncelerini aktaran bir yazı türü'], 'Roman, olay anlatan epik bir türdür.'),
  ('Aşağıdakilerden hangisi sahnelenmeye bağlı edebî türdür?', 'Komedi', ['Hikâye, kısa bir olay anlatısı', 'Masal, olağanüstü olayları anlatan halk anlatısı', 'Mektup, bir kişiye gönderilen yazılı anlatım'], 'Komedi sahnede oynanmak için yazılan oyun türüdür.'),
  ('Duyguların ve heyecanların dile getirildiği şiirler ve ağıt gibi türler hangi grupta yer alır?', 'Coşku ve heyecanı dile getiren metinler', ['Öğretmeye bağlı metinler, bilgilendirici ve eğitici yazılar', 'Sahnelenmeye bağlı metinler, oyun ve temsil', 'Anlatmaya bağlı metinler, olay anlatan hikâyeler'], 'Lirik şiir ve ağıt, coşku ve heyecan metinleridir.'),
  ('Bir yazarın görüştüğü kişinin sorulu yanıtlı konuşmalarını gazeteye aktarması hangi türdür?', 'Söyleşi', ['Deneme, kişisel düşünce yazısı', 'Mektup, bir kişiye yazılan yazı', 'Günlük, tarihli kişisel notlar'], 'Soru-cevap biçiminde aktarım söyleşidir.'),
  ('Bir yazar kendi yaşamını, başkasının yazmasını beklemeden ilk elden anlatıyorsa yazı hangi türdür?', 'Otobiyografi', ['Biyografi, başkası tarafından yazılan hayat öyküsü', 'Roman, kurmaca uzun anlatı', 'Fıkra, gazete yazısı'], 'Kişinin kendi yaşamını anlatması otobiyografidir.'),
  ('Bir yazarın, bir şairin hayatını araştırmalara dayanarak anlattığı eser için hangisi doğrudur?', 'Biyografidir', ['Otobiyografidir', 'Günlüktür', 'Fıkradır'], 'Bir başkasının yaşamını belgelere dayanarak anlatan eser biyografidir.'),
  ('Sahne açıldığında oyuncuların yeni bir mekâna geçmesi ya da bir kişinin girişi ile çıkışı sırasında oluşan küçük bölümlere ne ad verilir?', 'Sahne', ['Perde, büyük bölüm', 'Prolog, tanıtma', 'Epilog, kapanış'], 'Perde içindeki küçük bölümler sahne olarak adlandırılır.'),
  ('Bir oyuncunun maske, kostüm ve makyajla başka biri olarak sahneye çıkması hangi sanatın temel özelliğidir?', 'Canlandırma', ['Bilinç akışı', 'Betimleme', 'Hiciv'], 'Oyuncunun başka birini canlandırması tiyatronun temelidir.'),
  ('Bilimsel buluşların ve gelecekteki teknolojinin insan yaşamına etkisini kurgulayan roman türüne ne ad verilir?', 'Bilimkurgu romanı', ['Tarihî roman, geçmiş dönemi anlatan eser', 'Polisiye roman, soruşturma temalı eser', 'Köy romanı, kırsal yaşamı işleyen eser'], 'Bilimsel buluşlar ve gelecek tasarımları üzerine kurulu roman bilimkurgudur.'),
  ('Bir romanın tamamı mektuplardan oluşuyorsa bu romana ne ad verilir?', 'Mektup roman', ['Çerçeve roman, iç içe anlatı kuran eser', 'Otobiyografik roman, yazarın yaşamından esinli eser', 'Günlük roman, tarihli notlarla yazılan eser'], 'Mektuplarla oluşturulan roman mektup romandır.'),
  ('Bir ailenin ya da bir toplumun birkaç kuşağını kapsayan, çok sayıda kişi ve olaya yer veren çok ciltli uzun roman türüne ne ad verilir?', 'Nehir roman', ['Tarihî roman, geçmiş olaylara dayalı eser', 'Polisiye roman, suç temalı eser', 'Mektup roman, mektuplardan oluşan eser'], 'Birkaç kuşağın öyküsünü uzun bir akışla anlatan yapıt nehir romandır.'),
  ('Bir olayın başından sonuna, serim-düğüm-çözüm düzeniyle ele alındığı öykü türüne ne ad verilir?', 'Olay hikâyesi', ['Durum hikâyesi, kesit anlatan öykü', 'Fabl, hayvanlı öğretici hikâye', 'Masal, olağanüstü anlatı'], 'Olaya dayalı, çözümlü hikâye olay hikâyesidir.'),
  ('Birkaç cümleden oluşan, çoğu zaman tek bir olay ya da duyguyu yoğunlaştıran çok kısa anlatılara ne ad verilir?', 'Çok kısa öykü', ['Nehir roman, çok ciltli roman', 'Novella, orta uzunlukta anlatı', 'Destan, kahramanlık anlatısı'], 'Birkaç cümlelik yoğun anlatılar mikro öykü olarak adlandırılır.'),
  ('Acı, kırıcı ve iğneleyici bir dille bir kişiyi ya da durumu alaya alan söyleyişe ne ad verilir?', 'Sarkazm', ['İroni, söylenenin tersini kastetme', 'Nükte, ince ve zekice söz', 'Mübalağa, abartılı anlatım'], 'Acı ve kırıcı alay sarkazmdır.'),
  ('Dış görünüşte söylenenin tam tersinin kastedildiği, ince alay içeren söyleyişe ne ad verilir?', 'İroni', ['Sarkazm, kırıcı ve acı alay', 'Mübalağa, abartma', 'Tezat, karşıtlık'], 'Söylenenin tersini kastetme ironidir.'),
  ('\'Ne kadar yardımsever bir insansın, kapıyı yüzüme kapattın!\' cümlesinde hangi söyleyiş vardır?', 'İroni', ['Hüsnütalil, güzel bir nedene bağlama', 'Tevriye, iki anlamlı söz', 'Tenasüp, anlamca ilgili sözcükler'], 'Kapıyı yüze kapatan birine \'yardımsever\' demek söylenenin tersini kastetmektir.'),
  ('Toplumun aksayan yönlerini abartı ve alay yoluyla eleştiren edebî tür hangisidir?', 'Hiciv', ['Ağıt, ölüm acısı dile getiren tür', 'Pastoral, kır yaşamını öven tür', 'Methiye, övgü yazısı'], 'Aksaklıkları alayla eleştiren tür hicivdir.'),
  ('\'Kara mizah\' deyimi hangi tür gülmeceyi anlatır?', 'Ölüm ve acı gibi ciddi konuları alaycı bir tonla işleyen mizahı', ['Çocuklara yönelik masum mizahı', 'Sözcük oyunlarına dayalı mizahı', 'Şiir biçimli mizahı'], 'Kara mizah acı ve korkutucu konuları gülünç biçimde ele alır.'),
  ('Bir yazarın başka bir yazarın sözünü tırnak içinde ve adını belirterek metnine alması hangi yoldur?', 'Alıntı', ['Pastiş, üslup taklidi', 'Parodi, alaya alan taklit', 'İntihal, çalma'], 'Kaynağı gösterilerek yapılan aktarma alıntıdır.'),
  ('Bir yazarın başkasının metnini kaynak göstermeden kendi eseri gibi sunması hangi kavramla adlandırılır?', 'İntihal', ['Alıntı, kaynaklı aktarma', 'Pastiş, üslup taklidi', 'Telmih, gönderme'], 'Başkasının emeğini kaynak göstermeden kullanmak intihaldir.'),
  ('\'Yaz akşamı bahçemizde oturduk\' dizesi kaç hecelidir?', '11', ['9', '10', '12'], 'Ya-z ak-şa-mı bah-çe-mi-zde o-tur-duk biçiminde ünlüler sayıldığında dize on bir hecelidir.'),
  ('\'Kervan yola düzülür\' dizesinin hece sayısı ve durak düzeni hangi seçenekte doğru verilmiştir?', '7 hece, 4+3', ['8 hece, 4+4', '7 hece, 3+4', '6 hece, 3+3'], 'Ker-van yo-la - dü-zü-lür biçiminde yedi hecelidir ve duraklar 4+3 şeklindedir.'),
  ('\'Yağmur yağar damla damla\' dizesinin ölçü kalıbı hangisidir?', '4+4', ['5+3', '3+5', '6+2'], 'Yağ-mur ya-ğar - dam-la dam-la biçiminde dize 4+4 duraklı sekiz hecelidir.'),
  ('Hece ölçüsünde bir dizenin hece sayısı nasıl belirlenir?', 'Dizedeki ünlü harf sayısı sayılarak', ['Dizedeki sözcük sayısına bakılarak', 'Dizedeki ünsüz harf sayısı sayılarak', 'Dizedeki kafiyeli sözcük sayısına bakılarak'], 'Türkçede her hece bir ünlü içerdiğinden hece sayısı ünlü sayısına eşittir.'),
  ('Hece ölçüsünde \'durak\' ne demektir?', 'Dizenin içinde okurken yapılan kısa duraklama', ['Dizenin sonundaki uyak', 'Dörtlüğün bittiği yer', 'Şiirin başlığı'], 'Durak, dize içinde hece gruplarını ayıran kısa duraklamadır.'),
  ('\'4+4\' kalıbı ile yazılmış bir dizenin hece sayısı kaçtır?', '8', ['7', '6', '9'], '4+4 toplamı sekiz hecedir.'),
  ('Hece ölçüsüyle yazılan bir şiirde bütün dizelerin hece sayısı genellikle nasıldır?', 'Birbirine eşit tutulur', ['Her dize farklı uzunluktadır', 'Yalnız son dize farklıdır', 'Hece sayısı önemsizdir'], 'Hece ölçüsünün temel ilkesi dizelerin eşit hecelilik taşımasıdır.'),
  ('\'Eski bir türkü söyler bülbül\' dizesinin hece sayısı kaçtır?', '9', ['8', '10', '7'], 'Es-ki bir tür-kü söy-ler bül-bül biçiminde dokuz hece vardır.'),
  ('Dize sonları sırasıyla \'yol, kol, yaz, naz\' olan bir dörtlüğün uyak düzeni hangisidir?', 'Düz (aabb)', ['Çapraz (abab)', 'Sarmal (abba)', 'Uyaksız dörtlük'], 'İlk iki ve son iki dize ikişer ikişer uyaklıdır; bu düz uyaktır.'),
  ('Aşağıdaki dize çiftlerinden hangisi zengin uyak örneğidir?', 'bahar – kahar', ['göz – yaz', 'el – yol', 'dağ – taş'], 'Zengin uyakta ikiden çok ses benzerliği bulunur; bahar ile kahar -ahar sesleriyle zengin uyak oluşturur.'),
  ('Dize sonlarındaki sözcükler yazılışları aynı fakat anlamları farklıysa (\'yüz: sayı\' / \'yüz: surat\') bu uyağa ne ad verilir?', 'Cinaslı uyak', ['Yarım uyak, yalnız tek ses benzerliği', 'Tam uyak', 'Zengin uyak'], 'Yazılışı aynı anlamı farklı sözcüklerle yapılan uyak cinaslı uyaktır.'),
  ('Uyaksız yazılmış bir şiir için hangisi söylenebilir?', 'Beyaz şiirdir.', ['Mutlaka aruzla yazılmıştır.', 'Mutlaka koşmadır.', 'Kesinlikle kısa şiirdir.'], 'Ölçülü olup uyaksız şiire beyaz şiir denir.'),
  ('Maninin dörtlük uyak düzeni aşağıdakilerden hangisidir?', 'aaxa', ['abab', 'abba', 'aabb'], 'Mani, birinci, ikinci ve dördüncü dizeleri uyaklı, üçüncüsü serbest dörtlüktür.'),
  ('Şiir bilgisinde iç uyak terimi neyi ifade eder?', 'Dizenin içinde yer alan sözcüklerin birbiriyle uyaklı olması', ['Dize sonundaki uyağın tekrarı', 'Dizeler arasındaki sayısal ilişki', 'Şiirin başlığındaki ses benzerliği'], 'Dize içindeki sözcükler arasında yapılan uyağa iç uyak denir.'),
  ('Her biri dört dizeden oluşan üç bendli bir şiirin toplam dize sayısı kaçtır?', '12', ['7', '16', '9'], 'Üç bent, her biri dört dize olduğundan toplam on iki dizedir.'),
  ('\'Bir bahar sabahı koyunlarını otlatan çoban, derenin başında flütünü üfledi; kuşlar ona eşlik etti.\' dizelerine benzeyen bir şiirin türü hangisidir?', 'Pastoral', ['Satirik, alaycı şiir', 'Epik, kahramanlık şiiri', 'Didaktik, öğretici şiir'], 'Çoban ve doğa tasviri pastoral şiirin özelliğidir.'),
  ('\'Dürüst ol, çalış, israftan kaç; bu yol seni yüceltir.\' dizelerinin türü için ne söylenebilir?', 'Didaktik', ['Lirik, kişisel duygu şiiri', 'Epik, kahramanlık şiiri', 'Pastoral, kır şiiri'], 'Öğüt ve ders verme amacı didaktik niteliği gösterir.'),
  ('Bir şiirde yüklem dize başına alınarak \'Geldi bahar, açtı çiçek\' biçiminde söyleniyorsa bu söz dizimine ne ad verilir?', 'Devrik cümle', ['Kurallı cümle, öznenin başta yüklemin sonda olduğu cümle', 'Eksiltili cümle, bir öğesi atılmış cümle', 'Ters cümle, olumsuz yargılı cümle'], 'Yüklemin sonda yer almadığı cümleye devrik cümle denir.'),
  ('Bilinçdışına, düşlere ve otomatik yazıya önem veren; 1924\'te André Breton\'un manifestosuyla ilan edilen akım hangisidir?', 'Sürrealizm', ['Parnasizm, biçim kusursuzluğuna önem veren akım', 'Natüralizm, bilimsel gözleme dayanan akım', 'Klasisizm, akıl ve kurallara dayanan akım'], 'Breton\'un 1924 manifestosu sürrealizmin temelidir; otomatik yazı ve düş ögeleri öne çıkar.'),
  ('\'Varoluş özden önce gelir\' görüşüyle bilinen, özgürlük ve sorumluluk kavramlarını öne çıkaran düşünce akımı hangisidir?', 'Egzistansiyalizm', ['Romantizm, duygu ve bireycilik akımı', 'Realizm, gerçeğe sadakat akımı', 'Sembolizm, imgelerle anlatım akımı'], 'Sartre\'ın savunduğu varoluşçuluk, insanın kendini seçimleriyle yaratmasını vurgular.'),
  ('Dış dünyayı olduğu gibi yansıtmak yerine sanatçının iç dünyasındaki duyguları şiddetle dışa vurmasını öne çıkaran akım hangisidir?', 'Ekspresyonizm', ['Parnasizm, nesnellik ve biçim akımı', 'Klasisizm, kural akımı', 'Realizm, gözlem akımı'], 'Dışavurumculuk, sanatçının iç dünyasını güçlü biçimde yansıtmasına dayanır.'),
  ('Gerçekliği bilimsel bir kesinlikle, kalıtım ve çevre etkisini vurgulayarak inceleyen akım hangisidir?', 'Natüralizm', ['Romantizm, duygu akımı', 'Parnasizm, biçim akımı', 'Sembolizm, çağrışım akımı'], 'Kalıtım ve çevrenin belirleyici olduğu düşüncesi natüralizmin temel ilkesidir.'),
  ('Duyguları, düşleri ve doğaüstü öğeleri öne çıkaran, klasisizmin kurallarına karşı çıkan akım hangisidir?', 'Romantizm', ['Klasisizm, akıl ve kural akımı', 'Natüralizm, bilimsel gözlem akımı', 'Parnasizm, nesnel biçim akımı'], 'Romantizm duygu, hayal gücü ve bireyselliğe dayanarak klasik kurallara tepki gösterir.'),
  ('Gelecek ve hızı yücelten, makine ve teknolojiyi öven; 1909\'da Marinetti\'nin manifestosuyla başlayan akım hangisidir?', 'Fütürizm', ['Sembolizm, simgeci akım', 'Romantizm, duygu akımı', 'Klasisizm, kural akımı'], 'Marinetti\'nin 1909 tarihli manifestosuyla başlayan akım hız ve makineyi över.'),
  ('Bir kitabın başında yazarın eseri kime armağan ettiğini belirten kısa yazıya ne ad verilir?', 'İthaf', ['Önsöz, kitabın amacını açıklayan yazı', 'Kolofon, basım bilgilerinin yer aldığı bölüm', 'Dipnot, sayfa altındaki açıklama'], 'Eserin birine armağan edildiğini bildiren yazı ithaftır.'),
  ('Yazarın ya da bir başkasının kitabın başında, eserin yazılış amacını ve içeriğini açıkladığı yazıya ne ad verilir?', 'Önsöz', ['İthaf, armağan edilen kişi', 'Dizin, adlar listesi', 'Kaynakça, yararlanılan eserler listesi'], 'Eserin amacını ve kapsamını tanıtan başlangıç yazısı önsözdür.'),
  ('Bir eserin sonunda adlar, terimler ve konuların sayfa numaralarıyla alfabetik sıralandığı bölüme ne ad verilir?', 'Dizin', ['Önsöz, giriş yazısı', 'İthaf, armağan yazısı', 'Epigraf, başa konan söz'], 'Dizin, terimlerin ve adların bulunduğu sayfaları gösterir.'),
  ('Bir eserin yazılırken yararlanılan kaynakların listelendiği bölüm hangisidir?', 'Kaynakça', ['Dizin, adların sayfa gösterimi', 'Önsöz, açıklayıcı giriş', 'Ek, yardımcı belge'], 'Yararlanılan eserlerin listesi kaynakçadır.'),
  ('Sayfa altına konarak metindeki bir sözcüğü ya da ifadeyi açıklayan nota ne ad verilir?', 'Dipnot', ['Önsöz, kitap başı yazısı', 'Dizin, adlar listesi', 'Sonsöz, kitap sonu yazısı'], 'Sayfanın altında yer alan açıklama dipnottur.'),
  ('Bir kitabın ya da bölümünün başına, esere yön veren bir söz olarak konulan alıntıya ne ad verilir?', 'Epigraf', ['Dipnot, sayfa altı notu', 'Kaynakça, eser listesi', 'Dizin, terim listesi'], 'Esere yön veren alıntı sözü epigraftır.'),
  ('Bir eserin basım yılı, yayınevi ve baskı sayısı gibi bilgilerin yer aldığı bölüm için hangi terim kullanılır?', 'Künye', ['Önsöz, kitabın amacı yazısı', 'Dizin, adlar listesi', 'İthaf, armağan notu'], 'Yayın bilgilerini içeren sayfa künyedir.'),
  ('Bir yazarın dili kullanma biçimine, kendine özgü anlatım tarzına ne ad verilir?', 'Üslup', ['Tema, eserin ana konusu', 'Motif, tekrarlanan öge', 'Karakter, olay kişisi'], 'Yazarın dili kullanışındaki bireysel özellik üsluptur.'),
  ('Bir yazarın uzun, süslü ve ağır cümleler kurması, eski sözcüklere yer vermesi hangi üslup özelliğini gösterir?', 'Ağdalı üslup', ['Yalın üslup, süssüz ve açık anlatım', 'Konuşma dili üslubu, günlük dile yakın anlatım', 'Nesnel üslup, kişisel yorumdan arınmış anlatım'], 'Süslü ve ağır anlatım ağdalı üslubun özelliğidir.'),
  ('Süsten arınmış, kısa cümlelerle ve açık biçimde kurulan anlatım hangi üslupla ilişkilidir?', 'Yalın üslup', ['Ağdalı üslup, süslü ve ağır anlatım', 'Şiirsel üslup, imgelerle yüklü anlatım', 'Resmî üslup, kalıplaşmış dil'], 'Süssüz ve açık anlatım yalın üslubun özelliğidir.'),
  ('Bir eleştirmen, bir şiiri yazarının hayatındaki olaylar ışığında yorumluyorsa hangi yaklaşımı benimsemiştir?', 'Biyografik (yazar merkezli) yaklaşım', ['Metin merkezli yaklaşım, yalnız metne bakan yöntem', 'Okur merkezli yaklaşım, okurun yorumuna odaklanan yöntem', 'Yapısalcı yaklaşım, metnin iç yapısına odaklanan yöntem'], 'Eseri yazarın yaşamıyla açıklamak biyografik yaklaşımdır.'),
  ('Bir eleştirmen, eseri dönemin sınıf ilişkileri ve üretim koşulları bağlamında inceliyorsa hangi yaklaşımı kullanıyordur?', 'Marksist (toplumsal) eleştiri', ['Biçimci eleştiri, yalnız biçime bakan yöntem', 'Psikanalitik eleştiri, bilinçdışı odaklı yöntem', 'Feminist eleştiri, cinsiyet eşitsizliklerini sorgulayan yöntem'], 'Eseri sınıf ve üretim ilişkileriyle açıklayan yöntem Marksist eleştiridir.'),
  ('Edebî metinlerde kadın kişilerin nasıl temsil edildiğini ve cinsiyet kalıplarını sorgulayan eleştiri türü hangisidir?', 'Feminist eleştiri', ['Biyografik eleştiri, yazarın hayatına dayanan yöntem', 'Yapısalcı eleştiri, yapıyı çözümleyen yöntem', 'Biçimci eleştiri, biçim odaklı yöntem'], 'Temsilleri ve cinsiyet rollerini sorgulayan yaklaşım feminist eleştiridir.'),
  ('Tarihsel eleştiri bir eseri hangi bağlamda değerlendirir?', 'Yazıldığı dönemin koşulları ve olayları içinde', ['Yalnız yazarın niyeti açısından', 'Yalnız okurun beğenisine göre', 'Yalnız ses düzenine göre'], 'Tarihsel yöntem, eseri döneminin koşullarıyla açıklar.'),
  ('\'Sanat için sanat\' anlayışının temel savı nedir?', 'Sanat eseri, toplumsal bir amaç taşımadan yalnızca güzellik için yaratılmalıdır.', ['Sanat, toplumu eğitmek zorundadır.', 'Sanat, siyasetin hizmetindedir.', 'Sanat eseri yalnızca bilimsel olmalıdır.'], 'Bu görüş sanatı toplumsal yararcılıktan bağımsız sayar.'),
  ('\'Okulun bahçesindeki kavak, her sonbaharda yapraklarını tek tek bırakır; ben de her sonbaharda o sıraya dizilen ağaçların altında eski arkadaşlarımı arar dururdum.\' Bu parçada baskın duygu hangisidir?', 'Nostaljik bir özlem', ['Öfkeli bir isyan', 'Alaycı bir küçümseme', 'Korkulu bir telaş'], 'Geçmişteki arkadaşlara duyulan özlem, parçadaki baskın duygudur.'),
  ('\'Dağlar bir anda gürledi, gökyüzü kapkara bir yorgan gibi üstümüze çöktü; en güçlü adamın bile dizleri titredi.\' Bu cümlelerin yarattığı atmosfer hangisidir?', 'Korku ve gerilim', ['Huzur ve dinginlik', 'Neşe ve coşku', 'Alaycı hafiflik'], 'Gök gürültüsü, karanlık ve titreme korkuyu duyurur.'),
  ('\'Her sabah, penceremin önünde bir serçe öter; ben de çayımı yudumlayıp günün bana ne getireceğini umutla beklerim.\' Bu parçanın havasını en iyi hangisi belirtir?', 'Huzurlu ve umutlu', ['Gergin ve tehditkâr', 'Öfkeli ve isyankâr', 'Alaycı ve acımasız'], 'Serçenin sesi, çay ve umutla beklemek huzurlu bir hava kurar.'),
  ('\'Pazar yeri, balıkçıların haykırışlarıyla, çocuk kahkahalarıyla ve kızarmış simit kokusuyla bayram yerine dönmüştü.\' Bu parçada hangi atmosfer kurulmuştur?', 'Canlı ve neşeli', ['Kasvetli ve ıssız', 'Gerilimli ve karanlık', 'Hüzünlü ve durgun'], 'Gürültü, kahkaha ve koku canlı, şenlikli bir ortam yaratır.'),
  ('\'Sizce okul hayatının en zor yanı ne?\' diye sordum. \'Sabah erken kalkmak,\' dedi gülerek. \'Ama derslerden çok arkadaşlarımı özlerim.\' Bu parça hangi türe benzemektedir?', 'Söyleşi', ['Günlük, kişisel not', 'Makale, bilimsel inceleme', 'Anı, geçmişi anlatan yazı'], 'Soru-cevap biçimindeki aktarım söyleşidir.'),
  ('\'Akşam çöktü yavaşça, / Sokaklar boşaldı. / Kandiller tek tek yandı, / Rüzgâr bir şarkı taşıdı.\' Bu parça hangi türe girer?', 'Şiir', ['Makale, kanıtlı yazı', 'Fıkra, nükteli yazı', 'Mektup, hitaplı yazı'], 'Dizelere bölünmüş ve imgelerle kurulu anlatım şiirdir.'),
  ('Söylenen bir sözden vazgeçip yerine ondan daha etkili bir söz söylemeye ne ad verilir?', 'Rücu', ['İstifham, soru sorma sanatı', 'Nida, seslenme sanatı', 'Tekrir, sözcük yineleme sanatı'], 'Sözünden dönerek daha güçlü bir söz söylemek rücudur.'),
  ('\'Bir şeyi söylemeyip onu düşündürerek bilmezlikten gelme\' biçiminde yapılan söz sanatı hangisidir?', 'Tecahül-i arif', ['Rücu, sözden dönme', 'Nida, seslenme', 'Tedric, dereceleme'], 'Bildiği hâlde bilmezlikten gelme tecahül-i arif sanatıdır.'),
  ('Antik Yunan\'dan gelen, ölüm ya da kayıp üzerine yazılmış ağıt niteliğindeki şiire ne ad verilir?', 'Elegi', ['Haiku, kısa Japon şiiri', 'Sone, on dört dizeli şiir', 'Ode, coşkulu övgü şiiri'], 'Kayıp ve ölüm temalı hüzünlü şiir elegidir.'),
  ('Olay anlatan, hikâye niteliği taşıyan ve genellikle halk geleneğinden beslenen şiire ne ad verilir?', 'Balad', ['Haiku, çok kısa şiir', 'Elegi, ağıt şiiri', 'Ode, övgü şiiri'], 'Anlatı özelliği olan, öyküleyici şiir baladdır.'),
  ('Ölçü ve uyak kaygısını bırakıp iç ritme dayanan, nesre yaklaşan Batı kökenli şiir anlayışı için hangi terim kullanılır?', 'Serbest şiir', ['Sone, on dört dizelik kalıplı bir şiir biçimi', 'Haiku, Japon şiiri', 'Pastoral şiir, kır şiiri'], 'Geleneksel ölçü ve uyaktan arınmış şiire serbest şiir denir.'),
  ('Kısa, öğüt veren ve özlü anlatan, kimi zaman bir yazarın adıyla anılan söze ne ad verilir?', 'Aforizma', ['Sone, on dört dizelik şiir biçimi', 'Haiku, kısa şiir', 'Elegi, ağıt şiiri'], 'Özlü ve öğüt veren söz aforizmadır.'),
  ('\'Kapı gıcırdayarak açıldı. Eski sandalyenin kenarına tozlu bir battaniye atılmıştı. Pencere camında bir çatlak vardı ve sokak lambasının ışığı oradan odaya sızıyordu.\' Bu parçada ağırlıklı anlatım biçimi hangisidir?', 'Betimleme', ['Diyalog, karşılıklı konuşma', 'İç monolog, düşünceyi aktarma', 'Tartışma, görüşü savunma'], 'Nesne ve mekân ayrıntılarıyla görünüm anlatıldığı için betimleme ağır basar.'),
  ('\'Gündüz sustum, gece çığlık oldum.\' dizesinde hangi söz sanatı vardır?', 'Tezat', ['Teşbih, benzetme', 'Hüsnütalil, güzel nedene bağlama', 'Tenasüp, anlamca ilişki'], 'Gündüz-gece, susmak-çığlık atmak karşıt kavramlardır.'),
  ('\'Uzak bir dağ gibi sustu babam; / Kapıda kalan eski paltosu gibi.\' dizelerinde hangi söz sanatı belirgindir?', 'Teşbih', ['İstiare, bir benzeyen ya da benzetileni söylememe', 'Kinaye, dolaylı anlatım', 'Telmih, bilinen bir olaya gönderme'], '\'Gibi\' edatıyla yapılan benzetmeler teşbihtir.'),
  ('\'Güneş yükselir gölgem küçülür.\' dizesinin hece sayısı kaçtır?', '10', ['9', '11', '12'], 'Gü-neş yük-se-lir göl-gem kü-çü-lür biçiminde on hece vardır.'),
  ('Bir edebî eserin \'kurmaca\' olması ne anlama gelir?', 'Olay, kişi ve mekânın yazarca hayal gücüyle kurulmuş olması', ['Her olayın gerçek bir kaynağa dayanması', 'Anlatıcının yalnız tarih bilgisi aktarması', 'Eserin yalnız dilbilgisi kurallarını öğretmesi'], 'Kurmaca, yazarın tasarladığı, gerçekliğe dayanabilecek ama doğrudan gerçek olmayan bir dünyadır.'),
  ('Bir şairin kendi şiirlerini seçip bir araya getirdiği yayına hangi ad verilir?', 'Seçki', ['Derleme, halk ürünlerinin toplanması', 'Külliyat, bütün eserlerin toplamı', 'Kaynakça, yararlanılan eserler listesi'], 'Şairin kendi eserlerinden seçtiği yayın seçkidir.'),
  ('Farklı yazarların eserlerinden seçilen parçaların bir araya getirildiği kitaba ne ad verilir?', 'Antoloji', ['Külliyat, tek yazarın tüm eserleri', 'Önsöz, giriş yazısı', 'Dizin, adlar listesi'], 'Birden çok yazardan seçme parçalar toplayan yayın antolojidir.'),
  ('Bir edebî topluluğun ya da akımın görüşlerini ve ilkelerini açıklayan bildiriye ne ad verilir?', 'Manifesto', ['Önsöz, giriş yazısı', 'Epigraf, başa konan söz', 'Kolofon, basım notu'], 'Akım ya da topluluğun ilkelerini duyuran bildiri manifestodur.'),
  ('Bir sözcüğün düz anlamına ek olarak bireylerde ve toplumlarda uyandırdığı duygusal çağrışımlara ne ad verilir?', 'Konotasyon', ['Denotasyon, sözlükteki nesnel karşılık', 'Terim anlam, bilimsel kullanım', 'Eş anlam, yakın anlamlı sözcük'], 'Sözcüğün çağrışım yoluyla kazandığı ek anlamlar konotasyondur.'),
  ('\'Çocuk, ağaca tırmanan bir sincap gibi çevikti.\' cümlesindeki teşbihin yönü (ortak özelliği) hangisidir?', 'Çeviklik', ['Ağaç sevgisi', 'Sincabın kuyruğu', 'Çocuğun yaşı'], 'Çocuk ile sincap arasındaki benzerlik çeviklikte toplanır.'),
  ('\'Okuma saati başlamıştı. Sınıfta yalnızca sayfa çevirme sesi vardı; kalemlerin ucu bile susmuştu.\' Bu parçanın yarattığı atmosfer hangisidir?', 'Sessiz ve odaklanmış', ['Gürültülü ve kaotik, her yanda yükselen sesler', 'Korkulu ve gergin, bir tehlikenin yaklaşması', 'Neşeli ve hareketli, çocukların oyun oynadığı bir hava'], 'Yalnız sayfa sesi ve susan kalemler dingin bir ortamı gösterir.'),
  ('\'Yağmur, çatıda bir davul gibi çalıyordu; ben ise yatağımda, onun ritmine uyup uykuya dalıyordum.\' Bu cümlede \'davul gibi\' ifadesinin ortak yönü hangisidir?', 'Ritimli ve sürekli ses çıkarma', ['Yuvarlak biçim, dolgun görünüm', 'Hızlı hareket, çabuk koşma', 'Parlak renk, göz alıcı görünüm'], 'Yağmur ile davul arasındaki benzerlik ritimli sestir.'),
];
